using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.EventSystems;using UnityEditor;using ConvexHullDemo3D;
public static class VerifyHull3DContextMenu {
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 public static async Task<string> Run(){bool bg=Application.runInBackground;Application.runInBackground=true;var d=UnityEngine.Object.FindFirstObjectByType<ConvexHull3DController>();var original=d.Points.Select(p=>p.Position).ToArray();var selection=d.SelectedId;try {
 EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();await Task.Delay(400);
 var point=d.AddInFront();d.FlushChanges();Vector2 screen=d.worldCamera.WorldToScreenPoint(point.Position);Check(d.HitTest(screen)==point.Id,"Target hit");int count=d.Points.Count;int rev=d.HullRevision;
 d.Select(null);var rotation=d.worldCamera.transform.rotation;d.BeginRight(screen);d.EndRight(screen);Check(d.IsMenuOpen&&!d.IsFlying&&d.SelectedId==point.Id,"Right click selects previously unselected point and opens menu without fly");Check(d.worldCamera.transform.rotation==rotation,"Camera unchanged");
 await Task.Delay(250);Canvas.ForceUpdateCanvases();var button=d.ContextMenu.deleteButton;var canvas=button.GetComponentInParent<Canvas>().rootCanvas;var r=(RectTransform)button.transform;var pos=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,r.TransformPoint(r.rect.center));var e=new PointerEventData(EventSystem.current){position=pos,button=PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Check(hits.Count>0&&ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,ExecuteEvents.pointerClickHandler)==button.gameObject,"Delete UI click: "+string.Join(",",hits.Select(h=>h.gameObject.name)));d.FlushChanges();Check(d.Points.Count==count-1&&!d.Points.Any(p=>p.Id==point.Id)&&d.SelectedId==null&&!d.IsMenuOpen&&d.HullRevision==rev+1,"Target deleted, selection cleared, hull updated");
 point=d.AddInFront();screen=d.worldCamera.WorldToScreenPoint(point.Position);d.BeginRight(screen);d.ContinueRight(screen+new Vector2(8,0),Vector3.zero);Check(d.IsFlying&&!d.IsMenuOpen,"Right drag still flies");d.EndRight(screen+new Vector2(8,0));Check(!d.IsMenuOpen,"Drag does not open menu");d.BeginRight(screen);d.ContinueRight(screen,Vector3.forward);Check(d.IsFlying,"WASD gesture still flies");d.EndRight(screen);
 d.BeginRight(screen);d.EndRight(screen);Check(d.IsMenuOpen,"Reopen");d.CancelGestures();Check(!d.IsMenuOpen,"Pause/focus cancellation closes");d.IsScenePaused=true;Check(!d.OpenContextMenu(screen),"Paused blocked");d.IsScenePaused=false;d.SetTeachingMode(true);Check(!d.OpenContextMenu(screen),"Teaching blocked");d.SetTeachingMode(false);
 d.Select(point.Id);d.BeginRight(screen);d.EndRight(screen);d.ClearPoints();Check(!d.IsMenuOpen,"Clear closes menu");
 return "PASS: selected point right-click, real menu raycast/delete, hull revision, camera unchanged on click, right-drag and movement navigation, pause/teaching locks, cleanup";
 }finally{d.IsScenePaused=false;if(d.IsTeaching)d.SetTeachingMode(false);d.ClearPoints();foreach(var p in original)d.AddPoint(p,false);d.FlushChanges();Application.runInBackground=bg;}}
 public static string Preview(){var d=UnityEngine.Object.FindFirstObjectByType<ConvexHull3DController>();var p=d.AddInFront();d.FlushChanges();d.OpenContextMenu(d.worldCamera.WorldToScreenPoint(p.Position));return "Menu preview";}
}
